# Generate a bipartite graph K_{8,9} with 17 vertices
# Partition A: 0-7, Partition B: 8-16
# All edges go between partitions, so no triangles exist (girth >= 4)

edges = []
for u in range(8):
    for v in range(8, 17):
        edges.append((u, v))

print(f"Number of edges: {len(edges)}")
print(f"First few edges: {edges[:10]}")

# Verify no triangles exist
def has_triangle(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False

print(f"Has triangle: {has_triangle(edges, 17)}")
print("Graph is triangle-free, so girth >= 4")

